# Запрос конкретных полей
query {
user(id: 1) {
id
name
email
}
}

# Запрос списка с полями
query {
users(limit: 10) {
id
name
avatarUrl
}
}

query GetUser($id: ID!) {
user(id: $id) {
id
name
email
posts {
title
createdAt
}
}
}

# Создание пользователя
mutation CreateUser($input: CreateUserInput!) {
createUser(input: $input) {
id
name
email
}
}

# Обновление
mutation UpdateUser($id: ID!, $input: UpdateUserInput!) {
updateUser(id: $id, input: $input) {
id
name
email
}
}

# Удаление
mutation DeleteUser($id: ID!) {
deleteUser(id: $id) {
success
message
}
}

query GetUserWithPosts($id: ID!) {
user(id: $id) {
id
name
email
posts {
id
title
content
comments {
id
text
author {
name
}
}
}
}
}

import 'package:graphql_flutter/graphql_flutter.dart';

void main() async {
final ValueNotifier<GraphQLClient> client = createGraphQLClient();

runApp(
GraphQLProvider(
client: client,
child: MyApp(),
),
);
}

ValueNotifier<GraphQLClient> createGraphQLClient() {
final HttpLink httpLink = HttpLink(
'https://api.example.com/graphql',
);

return ValueNotifier(
GraphQLClient(
cache: GraphQLCache(),
link: httpLink,
),
);
}

// Query с помощью runQuery
final QueryOptions options = QueryOptions(
document: gql('''
query GetUsers {
users {
id
name
email
}
}
'''),
);

final QueryResult result = await client.query(options);

if (result.hasException) {
print('Ошибка: ${result.exception}');
} else {
final List<dynamic> users = result.data!['users'];
for (var user in users) {
print('${user['name']} — ${user['email']}');
}
}

final QueryOptions options = QueryOptions(
document: gql('''
query GetUser($id: ID!) {
user(id: $id) {
id
name
email
posts {
title
createdAt
}
}
}
'''),
variables: {'id': '1'},
);

final QueryResult result = await client.query(options);
final Map<String, dynamic> data = result.data!;
final user = data['user'];

final MutationOptions options = MutationOptions(
document: gql('''
mutation CreateUser($name: String!, $email: String!) {
createUser(input: {name: $name, email: $email}) {
id
name
email
}
}
'''),
variables: {
'name': 'Иван Петров',
'email': 'ivan@example.com',
},
);

final QueryResult result = await client.mutate(options);

if (result.hasException) {
print('Ошибка: ${result.exception}');
} else {
final newUser = result.data!['createUser'];
print('Создан: ${newUser['name']}');
}

final SubscriptionOptions options = SubscriptionOptions(
document: gql('''
subscription OnNewMessage {
onNewMessage {
id
text
sender {
name
}
}
}
'''),
);

client.subscribe(Options(options)).listen(
(result) {
final message = result.data!['onNewMessage'];
print('Новое сообщение: ${message['text']}');
},
onError: (error) {
print('Ошибка подписки: $error');
},
);

class UserListWidget extends StatelessWidget {
@override
Widget build(BuildContext context) {
return GraphQLQuery(
options: QueryOptions(
document: gql('query { users { id name email } }'),
),
builder: (BuildResult result, {VoidCallback? refetch, FetchMore? fetchMore}) {
if (result.loading) {
return const Center(child: CircularProgressIndicator());
}

if (result.hasException) {
return Center(child: Text('Ошибка: ${result.exception}'));
}

final List<dynamic> users = result.data!['users'];
return ListView.builder(
itemCount: users.length,
itemBuilder: (context, index) {
final user = users[index];
return ListTile(
title: Text(user['name']),
subtitle: Text(user['email']),
);
},
);
},
);
}
}
